package vn.iotstar.config; import lombok.RequiredArgsConstructor; import org.springframework.context.annotation.*; import org.springframework.security.authentication.*; import org.springframework.security.authentication.dao.DaoAuthenticationProvider; import org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.core.userdetails.UserDetailsService; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain;
@Configuration @EnableMethodSecurity @RequiredArgsConstructor public class SecurityConfig { private final UserDetailsService userDetailsService; @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean DaoAuthenticationProvider authenticationProvider(){DaoAuthenticationProvider p=new DaoAuthenticationProvider(userDetailsService);p.setPasswordEncoder(passwordEncoder());return p;} @Bean AuthenticationManager authenticationManager(AuthenticationConfiguration c)throws Exception{return c.getAuthenticationManager();} @Bean SecurityFilterChain securityFilterChain(HttpSecurity http)throws Exception{http.authorizeHttpRequests(a->a.requestMatchers("/login","/css/**","/js/**","/images/**","/uploads/**").permitAll().requestMatchers("/admin/**").hasRole("ADMIN").anyRequest().authenticated()).formLogin(f->f.loginPage("/login").loginProcessingUrl("/login").defaultSuccessUrl("/",true).failureUrl("/login?error=true").permitAll()).logout(l->l.logoutUrl("/logout").logoutSuccessUrl("/login?logout=true").invalidateHttpSession(true).deleteCookies("JSESSIONID").permitAll());return http.build();} }
